<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Servis extends Model { protected $table='servis'; protected $primaryKey='id_servis'; protected $guarded=['id_servis','kode_servis','id_transaksi','id_booking_servis','id_pelanggan','id_kendaraan_pelanggan','id_petugas','id_service_advisor','status','biaya_jasa','biaya_sparepart','total_biaya']; protected function casts():array{return ['tanggal_masuk'=>'datetime','tanggal_selesai'=>'datetime','kilometer'=>'integer','biaya_jasa'=>'decimal:2','biaya_sparepart'=>'decimal:2','total_biaya'=>'decimal:2','created_at'=>'datetime','updated_at'=>'datetime'];} public function bookingServis(){return $this->belongsTo(BookingServis::class,'id_booking_servis','id_booking_servis');} public function transaksi(){return $this->belongsTo(Transaksi::class,'id_transaksi','id_transaksi');} public function pelanggan(){return $this->belongsTo(Pelanggan::class,'id_pelanggan','id_pelanggan');} public function kendaraan(){return $this->belongsTo(KendaraanPelanggan::class,'id_kendaraan_pelanggan','id_kendaraan_pelanggan');} public function petugas(){return $this->belongsTo(Petugas::class,'id_petugas','id_petugas');} public function serviceAdvisor(){return $this->belongsTo(Petugas::class,'id_service_advisor','id_petugas');} public function details(){return $this->hasMany(DetailServis::class,'id_servis','id_servis');} public function sparepartItems(){return $this->hasMany(ServisSparepart::class,'id_servis','id_servis');} public function findings(){return $this->hasMany(ServiceFinding::class,'id_servis','id_servis');} public function approvalRequests(){return $this->hasMany(ServiceApprovalRequest::class,'id_servis','id_servis');} public function executionEvents(){return $this->hasMany(ServiceExecutionEvent::class,'id_servis','id_servis');} public function qualityControl(){return $this->hasOne(ServiceQualityControl::class,'id_servis','id_servis');} public function assignments(){return $this->hasMany(ServiceWorkOrderAssignment::class,'id_servis','id_servis');} public function activeAssistants(){return $this->hasMany(ServiceWorkOrderAssignment::class,'id_servis','id_servis')->where('assignment_role','assistant')->whereNull('unassigned_at');} }
